bool BookToc::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{

    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }

    if(pJson.isMember("book_id"))
    {
        if(!validJsonOfField(1, "book_id", pJson["book_id"], err, true))
            return false;
    }

    else
    {
        err="The book_id column cannot be null";
        return false;
    }

    if(pJson.isMember("title"))
    {
        if(!validJsonOfField(2, "title", pJson["title"], err, true))
            return false;
    }

    else
    {
        err="The title column cannot be null";
        return false;
    }

    if(pJson.isMember("level"))
    {
        if(!validJsonOfField(3, "level", pJson["level"], err, true))
            return false;
    }

    if(pJson.isMember("page_number"))
    {
        if(!validJsonOfField(4, "page_number", pJson["page_number"], err, true))
            return false;
    }

    else
    {
        err="The page_number column cannot be null";
        return false;
    }

    if(pJson.isMember("position"))
    {
        if(!validJsonOfField(5, "position", pJson["position"], err, true))
            return false;
    }

    else
    {
        err="The position column cannot be null";
        return false;
    }

    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(6, "created_at", pJson["created_at"], err, true))
            return false;
    }

    return true;
}
